/** Real Android/WebView UI contract; no remote model or invented social data. */
public class OceanMenuTest {
 ActivityScenario<MainActivity> scenario;MainActivity a;
 static String js(WebView v,String code)throws Exception{CountDownLatch l=new CountDownLatch(1);AtomicReference<String> result=new AtomicReference<>();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->v.evaluateJavascript(code,r->{result.set(r);l.countDown();}));assertTrue(l.await(5,TimeUnit.SECONDS));return result.get();}
 interface Check{boolean run()throws Exception;}
 static void until(Check c)throws Exception{long end=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<end){if(c.run())return;Thread.sleep(100);}fail("UI condition did not become true");}
 void ok(String code)throws Exception{assertEquals(code,"true",js(a.shell,code));}
 void run(String code)throws Exception{js(a.shell,code);}
 void openMenu()throws Exception{run("document.getElementById('menu').click()");ok("!document.getElementById('settings').hidden");}
 void shot(String name)throws Exception{Thread.sleep(250);ParcelFileDescriptor p=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand("screencap -p /sdcard/"+name+".png");try(java.io.InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){byte[] buf=new byte[1024];while(in.read(buf)!=-1){}}}
 @Before public void before()throws Exception{scenario=ActivityScenario.launch(MainActivity.class);scenario.onActivity(v->a=v);until(()->"true".equals(js(a.shell,"!!window.OSMINOG?.nativeReady")));run("document.getElementById('welcomeWake')?.click();document.getElementById('welcomeScreen')?.remove();records=[];localStorage.setItem('osminogPersonalOceanV1','[]');document.getElementById('text').value='';notice();render();setMenu(false);collapseSettings(true)");}
 @After public void after(){if(scenario!=null)scenario.close();}
 @Test public void arrowCollapsesOnlySettings()throws Exception{openMenu();run("document.getElementById('settingsToggle').click()");ok("document.getElementById('settingsBlock').hidden&&!document.getElementById('settings').hidden&&document.getElementById('profileBlock').offsetHeight>0&&document.getElementById('subscriptionsToggle').offsetHeight>0&&document.getElementById('intentionsToggle').offsetHeight>0");}
 @Test public void arrowExpandsSettingsWithoutClosingMenu()throws Exception{openMenu();run("document.getElementById('settingsToggle').click();document.getElementById('settingsToggle').click()");ok("!document.getElementById('settingsBlock').hidden&&!document.getElementById('settings').hidden");}
 @Test public void realTapCanReachArrow()throws Exception{openMenu();String raw=js(a.shell,"JSON.stringify((()=>{let r=document.getElementById('settingsToggle').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2}})())");JSONObject point=new JSONObject((String)new JSONTokener(raw).nextValue());int[] loc=new int[2];scenario.onActivity(v->v.shell.getLocationOnScreen(loc));float d=a.getResources().getDisplayMetrics().density,x=(float)point.getDouble("x")*d+loc[0],y=(float)point.getDouble("y")*d+loc[1];long t=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(t,t+80,MotionEvent.ACTION_UP,x,y,0);try{InstrumentationRegistry.getInstrumentation().sendPointerSync(down);InstrumentationRegistry.getInstrumentation().sendPointerSync(up);}finally{down.recycle();up.recycle();}until(()->"true".equals(js(a.shell,"document.getElementById('settingsBlock').hidden&&!document.getElementById('settings').hidden")));}
 @Test public void starClosesEntireMenu()throws Exception{openMenu();run("document.getElementById('menu').click()");ok("document.getElementById('settings').hidden&&!document.getElementById('main').inert");}
 @Test public void systemBackClosesMenuFirst()throws Exception{openMenu();scenario.onActivity(v->v.onBackPressed());until(()->"true".equals(js(a.shell,"document.getElementById('settings').hidden")));assertFalse(a.isFinishing());}
 @Test public void swipeBackClosesMenuNotJustSettings()throws Exception{openMenu();run("let s=document.getElementById('settings');s.dispatchEvent(new PointerEvent('pointerdown',{clientX:25,clientY:330}));s.dispatchEvent(new PointerEvent('pointerup',{clientX:160,clientY:332}))");ok("document.getElementById('settings').hidden");}
 @Test public void settingsCollapseSurvivesMenuReopen()throws Exception{openMenu();run("document.getElementById('settingsToggle').click();document.getElementById('menu').click();document.getElementById('menu').click()");ok("document.getElementById('settingsBlock').hidden&&!document.getElementById('settings').hidden");}
 @Test public void systemBackClosesDialogBeforeMenu()throws Exception{openMenu();run("document.getElementById('languageButton').click();OSMINOG.back()");ok("!document.getElementById('languageDialog').open&&!document.getElementById('settings').hidden");}
 @Test public void regularSendRemainsPrivateAndNoFabricatedReply()throws Exception{run("document.getElementById('text').value='Личная мысль';document.getElementById('composer').requestSubmit()");ok("records.length===1&&!records[0].intent&&document.querySelectorAll('.message.assistant').length===0&&document.getElementById('text').value===''");}
 @Test public void messageBubbleEditsText()throws Exception{run("ask('До');document.querySelector('.message .avatar').click();document.getElementById('editMessage').click();document.getElementById('editText').value='После';document.getElementById('saveEdit').click()");ok("records[0].text==='После'&&document.querySelector('.message .body').textContent==='После'");}
 @Test public void deletionNeedsConfirmation()throws Exception{run("ask('Удалить');document.querySelector('.message .avatar').click();document.getElementById('deleteMessage').click()");ok("records.length===1&&document.getElementById('confirmDialog').open");run("document.getElementById('confirmCancel').click()");ok("records.length===1");run("document.querySelector('.message .avatar').click();document.getElementById('deleteMessage').click();document.getElementById('confirmYes').click()");ok("records.length===0");}
 @Test public void holdingInputBubbleCreatesOnlyExplicitIntentDraft()throws Exception{run("document.getElementById('text').value='Ищу ушанку';document.getElementById('attach').dispatchEvent(new PointerEvent('pointerdown',{pointerId:1,pointerType:'touch',clientX:20,clientY:600}))");until(()->"true".equals(js(a.shell,"document.getElementById('confirmDialog').open")));run("document.getElementById('attach').dispatchEvent(new PointerEvent('pointerup',{pointerId:1,pointerType:'touch'}));document.getElementById('confirmYes').click()");ok("records.length===1&&records[0].intent&&!records[0].published&&document.getElementById('messages').textContent.includes('не опубликован')");}
 @Test public void attachmentTapDoesNotReleaseIntent()throws Exception{run("document.getElementById('text').value='Не публиковать';document.getElementById('attach').click()");ok("document.getElementById('attachmentDialog').open&&records.length===0&&!document.getElementById('confirmDialog').open");}
 @Test public void footerRespectsNativeNavigationInset()throws Exception{scenario.onActivity(v->v.applyInsets(24,48));Thread.sleep(150);ok("document.getElementById('eye').getBoundingClientRect().bottom<=innerHeight-48&&document.getElementById('attach').getBoundingClientRect().bottom<=innerHeight-48");}
 @Test public void keyboardInsetKeepsComposerAboveKeyboard()throws Exception{scenario.onActivity(v->v.applyInsets(24,300));Thread.sleep(150);ok("document.getElementById('eye').getBoundingClientRect().bottom<=innerHeight-300&&document.getElementById('text').getBoundingClientRect().height>=44");}
 @Test public void twoThemesAndProfilePersist()throws Exception{openMenu();run("applyOceanTheme('blue');document.getElementById('themeToggle').click();document.getElementById('profileName').value='Тестовое имя';document.getElementById('profileName').dispatchEvent(new Event('change'))");ok("document.body.classList.contains('theme-dark')&&JSON.parse(localStorage.getItem('osminogProfileV1')).name==='Тестовое имя'");}
 @Test public void oldHistoriesRemainPrivateAndReadable()throws Exception{run("localStorage.setItem('osminogVisionHistoryV2',JSON.stringify({'0':[{role:'user',text:'Личная старая запись'}]}))");openMenu();run("document.getElementById('legacyButton').click()");ok("document.getElementById('legacyMessages').textContent.includes('Личная старая запись')&&localStorage.getItem('osminogVisionHistoryV2').includes('Личная старая запись')&&records.length===0");}
 @Test public void noOldProvidersAndNoNetworkClaims()throws Exception{ok("!document.getElementById('providerSheet')&&!document.getElementById('connectionStatus')&&!document.body.textContent.includes('Подключить ИИ')&&document.getElementById('brainStatus').textContent.includes('не подключены')");assertFalse(MainActivity.trusted("https://chatgpt.com/"));assertFalse(MainActivity.trusted("https://appassets.androidplatform.net.evil.test/"));}
 @Test public void safeTextDoesNotExecuteHtml()throws Exception{run("ask('<img src=x onerror=alert(1)>')");ok("document.querySelectorAll('.message .body img').length===0&&records[0].text.includes('<img')");}
 @Test public void updateGuardsRemainActive()throws Exception{assertTrue(Updater.assetUrl("https://github.com/jeep-jim/OSMINOG-Releases/releases/download/vision-android-v0.2.6/OSMINOG-Vision-0.2.6.apk"));assertFalse(Updater.assetUrl("https://evil.test/app.apk"));}
 @Test public void welcomeStillHasLanguagesAndSafeBottom()throws Exception{run("localStorage.removeItem('osminogWelcomed')");scenario.onActivity(v->v.shell.reload());until(()->"true".equals(js(a.shell,"!!window.OSMINOG?.nativeReady&&!!document.getElementById('welcomeWake')")));scenario.onActivity(v->v.applyInsets(24,48));Thread.sleep(150);ok("document.querySelectorAll('#welcomeLanguage option').length===10&&document.getElementById('welcomeWake').getBoundingClientRect().bottom<=innerHeight-48");}
 @Test public void cameraCapturesLocallyAndStopsOnMenu()throws Exception{InstrumentationRegistry.getInstrumentation().getUiAutomation().grantRuntimePermission("com.osminog.vision",Manifest.permission.CAMERA);run("startCamera()");until(()->"true".equals(js(a.shell,"!!cameraStream&&document.getElementById('cameraVideo').videoWidth>0")));run("document.getElementById('captureFrame').click()");ok("!cameraStream&&pendingFile.type==='image/jpeg'&&pendingFile.data.startsWith('data:image/jpeg;base64,')&&records.length===0");run("startCamera()");until(()->"true".equals(js(a.shell,"!!cameraStream")));run("window.testCameraTrack=cameraStream.getVideoTracks()[0];setMenu(true)");ok("!cameraStream&&window.testCameraTrack.readyState==='ended'");}
 @Test public void menuScreenshotStates()throws Exception{run("applyOceanTheme('dark');notice()");openMenu();shot("vision-menu");run("collapseSettings(false)");shot("vision-menu-collapsed");run("applyOceanTheme('blue');collapseSettings(true)");shot("vision-menu-blue");run("setMenu(false);document.getElementById('text').value='Привет, что ты такое? =)))';typing()");shot("vision-home");}
}
